import ExcelJS from 'exceljs';

export const exportToExcel = (projectDetails, sections) => {
    const workbook = new ExcelJS.Workbook();
    const worksheet = workbook.addWorksheet('Project Details');

    // Function to apply different styles
    const applyStyles = (cell, style) => {
        cell.alignment = { vertical: 'middle', horizontal: 'center' };
        cell.font = { bold: true };
        cell.fill = {
            type: 'pattern',
            pattern: 'solid',
            fgColor: { argb: style.backgroundColor || 'FFFFFF' }, // Background color
            bgColor: { argb: 'FFFFFF' } // Default background color
        };
        cell.border = {
            top: { style: 'thin' },
            left: { style: 'thin' },
            bottom: { style: 'thin' },
            right: { style: 'thin' }
        };
        cell.numFmt = style.format || undefined; // Number format
    };

    // Add project details to the worksheet
    worksheet.addRow(['Project Name', projectDetails.projectName]);
    worksheet.addRow(['Client', projectDetails.client]);
    worksheet.addRow(['Contractor', projectDetails.contractor]);
    worksheet.addRow(['Consultant', projectDetails.consultant]);
    worksheet.addRow(['Title', projectDetails.title]);
    worksheet.addRow([]); // Empty row for spacing

    // Function to add sections and their data to the worksheet
    const addDataToSectionsSheet = (section, sectionIndex) => {
        const sectionStartRow = worksheet.rowCount + 1;

        // Add section name with specific style
        const sectionNameCell = worksheet.getCell(`A${sectionStartRow}`);
        sectionNameCell.value = `Section Name: ${section.section_name}`;
        applyStyles(sectionNameCell, { backgroundColor: '#FFCC99' }); // Example color

        worksheet.addRow([]); // Empty row for spacing

        if (section.subsections) {
            section.subsections.forEach((subsection, subsectionIndex) => {
                const subsectionStartRow = worksheet.rowCount + 1;

                // Add subsection name with specific style
                const subsectionNameCell = worksheet.getCell(`A${subsectionStartRow}`);
                subsectionNameCell.value = `Subsection Name: ${subsection.subsection_name}`;
                applyStyles(subsectionNameCell, { backgroundColor: '#FFFFCC' }); // Example color

                worksheet.addRow([]); // Empty row for spacing

                if (subsection.documents) {
                    subsection.documents.forEach((document) => {
                        // Add document details with specific style
                        const documentNameCell = worksheet.getCell(`A${worksheet.rowCount + 1}`);
                        documentNameCell.value = `Document Name: ${document.serial_number}-${document.document_name}`;
                        applyStyles(documentNameCell, { backgroundColor: '#CCEEFF' }); // Example color

                        worksheet.addRow(['Start Date', document.start_date || 'N/A']);
                        worksheet.addRow(['End Date', document.end_date || 'N/A']);
                        worksheet.addRow(['Status', document.status || 'N/A']);
                        worksheet.addRow(['Priority', document.priority || 'N/A']);
                        worksheet.addRow(['Assigned To', document.assigned_to || 'N/A']);
                        worksheet.addRow(['Progress', document.progress || 'N/A']);
                        worksheet.addRow([]); // Empty row for spacing
                    });
                }
            });
        }
    };

    // Iterate over sections and add their data
    if (sections) {
        sections.forEach((section, index) => {
            addDataToSectionsSheet(section, index);
        });
    }

    // Save the workbook
    workbook.xlsx.writeBuffer().then((buffer) => {
        const blob = new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `${projectDetails.projectName}_Details.xlsx`;
        a.click();
        URL.revokeObjectURL(url);
    });
};
